import kotlin.math.min

fun main() {
    val n = readln().toLong()
    val x = readln().toInt()
    val period = 6
    val k = (n % period).toInt()
    var pos = x
    for (i in k downTo 1) {
        if (i % 2 == 1) {
            // odd move: swap 0 and 1
            if (pos == 0) pos = 1
            else if (pos == 1) pos = 0
        } else {
            // even move: swap 1 and 2
            if (pos == 1) pos = 2
            else if (pos == 2) pos = 1
        }
    }
    println(pos)
}
